if (b.length == n) {
    return true;
}

if (n == 0) {
    deallocate(p, data, max_size, b);
    return true;
}

if (!b) {
    b = allocate(p, data, max_size, alignment, n);
    return b.ptr != nullptr;
}

const auto alignedLength = round_to_alignment(alignment, n);

// Check if it's the last allocated block (can expand/shrink in place)
if (is_last_used_block(data, p, b)) {
    if (static_cast<char*>(b.ptr) + alignedLength <= data + max_size) {
        b.length = alignedLength;
        p = static_cast<char*>(b.ptr) + alignedLength;
        return true;
    }
    // out of memory
    return false;
}

// If shrinking
if (b.length > n) {
    b.length = round_to_alignment(alignment, n);
    return true;
}

// Try to allocate a new block
block newBlock = allocate(p, data, max_size, alignment, alignedLength);
if (newBlock) {
    // Copy data from old block to new block
    std::memcpy(newBlock.ptr, b.ptr, std::min(b.length, newBlock.length));
    // Cannot deallocate the old block if it's not the last one, so just "leak" it
    b = newBlock;
    return true;
}

return false;

